"use strict";(globalThis.webpackChunkgrc||=[]).push([[19837],{67283(e){e.exports=JSON.parse('{"citeKey":"byna2003improvingperformance","slug":"byna-2003-improving-performance-468e","title":"Improving the Performance of MPI Derived Datatypes by Optimizing Memory-Access Cost","authors":["S. Byna","W. D. Gropp","X.-H. Sun","R. Thakur"],"venue":"The IEEE International Conference on Cluster Computing, 2003, Hong Kong","type":"Conference","entryType":"inproceedings","date":"December, 2003","year":2003,"era":"iit","month":12,"doi":"10.1109/clustr.2003.1253341","abstract":"The MPI Standard supports derived datatypes, which allow users to describe noncontiguous memory layout and communicate noncontiguous data with a single communication function. This feature enables an MPI implementation to optimize the transfer of noncontiguous data. In practice, however, few MPI implementations implement derived datatypes in a way that performs better than what the user can achieve by manually packing data into a contiguous buffer and then calling an MPI function. In this paper, the authors present a technique for improving the performance of derived datatypes by automatically using packing algorithms that are optimized for memory-access cost. The packing algorithms use memory-optimization techniques that the user cannot apply easily without advanced knowledge of the memory architecture. The authors present performance results for a matrix-transpose example that demonstrate that their implementation of derived datatypes significantly outperforms both manual packing by the user and the existing derived-datatype code in the MPI implementation (MPICH).","hasAbstract":true,"lede":"The authors present a technique for improving the performance of derived datatypes by automatically using packing algorithms that are optimized for memory-access cost.","links":{"pdf":"https://grc.iit.edu/papers/2003/byna-2003-improving-performance-468e.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["byna-surendra","sun-xian-he"]}')}}]);